<?php defined('BASEPATH') OR exit('No direct script access allowed');class Email_message_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function listing($org,$filters=array()){$this->db->where('organization_id',$org);foreach($filters as $k=>$v)if($v!==NULL&&$v!=='')$this->db->where($k,$v);$r=$this->db->order_by('received_at','DESC')->get('email_messages')->result_array();return array_map(array($this,'view'),$r);}function one($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('email_messages')->row_array();return $r?$this->view($r):NULL;}function create($org,$d){$now=date('Y-m-d H:i:s');$id=$this->uuid();$messageId=$d['messageId']??('<'.$id.'@windels.local>');$thread=$this->thread($org,$d['inReplyTo']??NULL,$d['threadId']??NULL,$id);$r=array('id'=>$id,'organization_id'=>$org,'mailbox_id'=>$d['mailboxId'],'thread_id'=>$thread,'message_id'=>$messageId,'direction'=>$d['direction']??'inbound','from_name'=>$d['fromName']??NULL,'from_address'=>$d['fromAddress'],'to_addresses'=>json_encode($d['to']??array()),'cc_addresses'=>json_encode($d['cc']??array()),'subject'=>$d['subject']??'(no subject)','body_text'=>$d['bodyText'],'body_html'=>$d['bodyHtml']??NULL,'sent_at'=>isset($d['sentAt'])&&$d['sentAt']?date('Y-m-d H:i:s',strtotime($d['sentAt'])):NULL,'received_at'=>$now,'labels'=>json_encode($d['labels']??array()),'is_read'=>!empty($d['isRead']),'attachments_count'=>$d['attachmentsCount']??0,'in_reply_to'=>$d['inReplyTo']??NULL,'reference_ids'=>json_encode($d['references']??array()),'contact_id'=>$d['contactId']??NULL,'deal_id'=>$d['dealId']??NULL,'company_id'=>$d['companyId']??NULL,'outbox_status'=>$d['outboxStatus']??'none','created_at'=>$now,'updated_at'=>$now);$this->db->insert('email_messages',$r);return $this->view($r);}private function thread($org,$reply,$thread,$fallback){if($thread)return $thread;if($reply){$p=$this->db->where(array('organization_id'=>$org,'message_id'=>$reply))->get('email_messages')->row_array();if($p)return $p['thread_id'];}return $fallback;}function update_message($id,$org,$d){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('email_messages')->row_array();if(!$r)return NULL;$map=array('isRead'=>'is_read','contactId'=>'contact_id','dealId'=>'deal_id','companyId'=>'company_id');$set=array('updated_at'=>date('Y-m-d H:i:s'));foreach($map as $i=>$o)if(array_key_exists($i,$d))$set[$o]=$d[$i];if(isset($d['labels']))$set['labels']=json_encode($d['labels']);$this->db->where('id',$id)->update('email_messages',$set);return $this->one($id,$org);}function remove($id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->delete('email_messages');return $this->db->affected_rows()>0;}function threads($org){$groups=$this->db->select('thread_id,mailbox_id,MAX(subject) subject,MAX(received_at) last_at,COUNT(*) count,SUM(is_read=0) unread')->where('organization_id',$org)->group_by(array('thread_id','mailbox_id'))->order_by('last_at','DESC')->get('email_messages')->result_array();$out=array();foreach($groups as $g)$out[]=array('threadId'=>$g['thread_id'],'organizationId'=>$org,'mailboxId'=>$g['mailbox_id'],'subject'=>$g['subject'],'lastActivityAt'=>$g['last_at'],'messageCount'=>(int)$g['count'],'participants'=>array(),'labels'=>array(),'unreadCount'=>(int)$g['unread'],'lastMessageId'=>$this->db->select('id')->where(array('organization_id'=>$org,'thread_id'=>$g['thread_id']))->order_by('received_at','DESC')->limit(1)->get('email_messages')->row_array()['id']);return $out;}function thread_detail($id,$org){$msgs=$this->listing($org,array('thread_id'=>$id));if(!$msgs)return NULL;$threads=$this->threads($org);foreach($threads as $t)if($t['threadId']===$id){$t['messages']=array_reverse($msgs);return $t;}return NULL;}function delivery($id,$org,$ok,$response,$error=NULL){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org,'direction'=>'outbound'))->get('email_messages')->row_array();if(!$r)return NULL;$now=date('Y-m-d H:i:s');$this->db->where('id',$id)->update('email_messages',array('outbox_status'=>$ok?'sent':'failed','outbox_error'=>$error,'smtp_response'=>$response,'delivered_at'=>$ok?$now:NULL,'sent_at'=>$ok?$now:$r['sent_at'],'updated_at'=>$now));return $this->one($id,$org);}function dashboard($org){$rows=$this->db->where('organization_id',$org)->get('email_messages')->result_array();$threads=array();$top=array();$last7=0;$counts=array('mailboxes'=>$this->db->where('organization_id',$org)->count_all_results('email_mailboxes'),'messages'=>count($rows),'unread'=>0,'inbound'=>0,'outbound'=>0,'queued'=>0,'sent'=>0,'failed'=>0,'threads'=>0);foreach($rows as $r){$threads[$r['thread_id']]=1;if(!$r['is_read'])$counts['unread']++;$counts[$r['direction']]++;if(isset($counts[$r['outbox_status']]))$counts[$r['outbox_status']]++;if(strtotime($r['received_at'])>=strtotime('-7 days'))$last7++;if($r['direction']==='inbound')$top[$r['from_address']]=($top[$r['from_address']]??0)+1;}$counts['threads']=count($threads);arsort($top);$senders=array();foreach(array_slice($top,0,5,TRUE) as $email=>$n)$senders[]=array('email'=>$email,'count'=>$n);return array('counts'=>$counts,'last7dMessages'=>$last7,'topSenders'=>$senders,'avgResponseMs'=>NULL,'unreadByMailbox'=>array(),'openThreads'=>array_slice($this->threads($org),0,10),'recentMessages'=>array_slice(array_map(array($this,'view'),array_reverse(array_slice($rows,-10))),0,10),'lastUpdatedAt'=>$rows?max(array_column($rows,'updated_at')):NULL);}function summarize($thread,$org){$d=$this->thread_detail($thread,$org);if(!$d)return NULL;$text='';$people=array();foreach($d['messages'] as $m){$text.=' '.$m['bodyText'];$people[]=$m['fromAddress'];}$sent=preg_split('/(?<=[.!?])\s+/',trim($text));return array('threadId'=>$thread,'summaryKind'=>'deterministic','summary'=>mb_substr(implode(' ',array_slice($sent,0,3)),0,1000),'participants'=>array_values(array_unique($people)),'messageCount'=>count($d['messages']),'dateRange'=>array('from'=>$d['messages'][0]['receivedAt'],'to'=>$d['messages'][count($d['messages'])-1]['receivedAt']),'keywords'=>array(),'actionables'=>array());}function triage($thread,$org){$d=$this->thread_detail($thread,$org);if(!$d)return NULL;$text=mb_strtolower(implode(' ',array_column($d['messages'],'bodyText')));$urgent=preg_match('/urgent|asap|immediately|deadline|overdue/',$text);$question=strpos($text,'?')!==FALSE;$score=$urgent?85:($question?55:20);return array('threadId'=>$thread,'triageKind'=>'heuristic','urgencyScore'=>$score,'label'=>$urgent?'urgent':($question?'needs_reply':'informational'),'suggestedAction'=>$urgent?'Respond promptly':($question?'Review and reply':'No immediate response required'),'reasons'=>array($urgent?'Urgency language detected':($question?'Question detected':'No urgent language detected')));} function view($r){return array('id'=>$r['id'],'organizationId'=>$r['organization_id'],'mailboxId'=>$r['mailbox_id'],'threadId'=>$r['thread_id'],'messageId'=>$r['message_id'],'direction'=>$r['direction'],'fromName'=>$r['from_name'],'fromAddress'=>$r['from_address'],'to'=>json_decode($r['to_addresses'],TRUE)?:array(),'cc'=>json_decode($r['cc_addresses'],TRUE)?:array(),'subject'=>$r['subject'],'bodyText'=>$r['body_text'],'bodyHtml'=>$r['body_html'],'sentAt'=>$r['sent_at'],'receivedAt'=>$r['received_at'],'labels'=>json_decode($r['labels'],TRUE)?:array(),'isRead'=>(bool)$r['is_read'],'attachmentsCount'=>(int)$r['attachments_count'],'inReplyTo'=>$r['in_reply_to'],'references'=>json_decode($r['reference_ids'],TRUE)?:array(),'contactId'=>$r['contact_id'],'dealId'=>$r['deal_id'],'companyId'=>$r['company_id'],'outboxStatus'=>$r['outbox_status'],'outboxError'=>$r['outbox_error'],'smtpResponse'=>$r['smtp_response'],'deliveredAt'=>$r['delivered_at']);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
